from collections import deque

class Solution:

	def partyHouse(self, N, adj):
		ans = N
		for i in range(1, N + 1):
			dist = [-1] * (N + 1)
			dist[i] = 0
			q = deque()
			q.append(i)
			max_dist = 0
			while len(q) > 0:
				v = q.popleft()
				for w in adj[v]:
					if dist[w] == -1:
						dist[w] = dist[v] + 1
						max_dist = max(max_dist, dist[w])
						q.append(w)
			ans = min(ans, max_dist)
		return ans
